using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioPhysicalCameraValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;static AnimationStudioWindow host;static MashBoxStudioViewport view;static StudioModelEditor ed;static StudioModelDocument doc;static Material source;static Texture2D grid;static int phase,checks,warmup;static double ready,deadline;static Color32[] matte,rough,glossy;static Quaternion lightBeforeOrbit;
 static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);
 static string Out(string n)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+n));
 public static void Run(){EditorApplication.delayCall+=()=>{try{ShaderUtil.allowAsyncCompilation=false;var global=Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineGlobalSettings, Unity.RenderPipelines.HighDefinition.Runtime");global.GetMethod("Ensure",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{true});var pipeline=(RenderPipelineAsset)ScriptableObject.CreateInstance(Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineAsset, Unity.RenderPipelines.HighDefinition.Runtime"));AssetDatabase.CreateAsset(pipeline,AssetDatabase.GenerateUniqueAssetPath("Assets/PhysicalCameraPipeline.asset"));GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Editor/MashBoxStudio_Prototype_Modeling_Shader.shadergraph");Check(shader,"Prototype shader missing");source=new Material(shader);string tex=source.HasTexture("_BaseMap")?"_BaseMap":source.HasTexture("_BaseColorMap")?"_BaseColorMap":"_GridTexture";grid=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Editor/PreviewGrid.png");Check(grid&&grid.width==512,"Imported grid not 512 pixels");source.SetTexture(tex,grid);source.SetColor("_Color",new Color(.65f,.65f,.65f));source.SetFloat("_Metallic",0);source.SetFloat("_Smoothness",0);AssetDatabase.CreateAsset(source,AssetDatabase.GenerateUniqueAssetPath("Assets/PhysicalCameraMaterial.mat"));doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Sphere,out var polys);doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutPolygons=polys,cutTriangles=mesh.triangles,materials=new[]{source}});doc.lighting.studioLights=false;doc.lighting.ground=false;AnimationStudioWindow.Open();host=Resources.FindObjectsOfTypeAll<AnimationStudioWindow>().First();typeof(AnimationStudioWindow).GetMethod("SwitchStudioMode",F).Invoke(host,new object[]{true});typeof(AnimationStudioWindow).GetMethod("LoadStudioModel",F).Invoke(host,new object[]{doc});ed=host.ToolbarModelEditor;view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().First(v=>v.Studio==host);view.position=new Rect(50,50,1000,800);view.modelGridVisible=false;view.LookAtDirect(Vector3.zero,Quaternion.Euler(10,20,0),1.2f);ed.SetModelDrawMode(view,DrawCameraMode.Textured);ed.SetXRayMode(false);ed.SetCheckerMap(false);ed.SetDisplayMode(true,true);ready=EditorApplication.timeSinceStartup+2;deadline=ready+120;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}};}
 static Color32[] Pixels(){var rt=Get(view,"cachedScene") as RenderTexture;if(!rt||!rt.IsCreated())return null;var old=RenderTexture.active;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();File.WriteAllBytes(Out("physical-camera-"+phase+".png"),t.EncodeToPNG());return t.GetPixels32();}finally{RenderTexture.active=old;Object.DestroyImmediate(t);}}
 static int Difference(Color32[] a,Color32[] b)=>a.Zip(b,(x,y)=>Math.Abs(x.r-y.r)+Math.Abs(x.g-y.g)+Math.Abs(x.b-y.b)).Count(d=>d>15);
 static void Tick(){if(EditorApplication.timeSinceStartup<ready)return;try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Native render timeout");if(warmup++<2){view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);ready=EditorApplication.timeSinceStartup+.5;return;}var p=Pixels();if(p==null){view.Repaint();return;}var actual=ed.Transforms[0].GetComponent<Renderer>().sharedMaterial;Check(!doc.lighting.studioLights,"Camera rig altered user's Studio Lights preference");if(phase<4)Check(actual.shader==source.shader,"Camera Lighting replaced the authored shader");if(phase==0){matte=p;Check(p.Select(c=>c.r).Distinct().Count()>30,"Native material rendering empty");source.SetFloat("_Metallic",1);Check(actual.GetFloat("_Metallic")==1,"Inspector-style material edit did not reach inherited preview");}
 else if(phase==1){rough=p;Check(actual.GetFloat("_Metallic")==1,"Metallic not retained");Check(Difference(matte,rough)>100,"Metallic has no rendered response");source.SetFloat("_Smoothness",1);Check(actual.GetFloat("_Smoothness")==1,"Smoothness edit did not reach inherited preview");}
 else if(phase==2){glossy=p;Check(actual.GetFloat("_Smoothness")==1,"Smoothness not retained");Check(Difference(rough,glossy)>50,"Smoothness has no rendered response");var lights=Get(ed,"previewLighting");var key=(Light)lights.GetType().GetField("Key",F).GetValue(lights);lightBeforeOrbit=key.transform.rotation;view.LookAtDirect(Vector3.zero,Quaternion.Euler(10,60,0),1.2f);typeof(StudioModelEditor).GetMethod("ConfigureLightingCamera",F).Invoke(ed,new object[]{view});source.SetFloat("_Metallic",0);source.SetFloat("_Smoothness",0);ed.SetDisplayMode(true,true);}
 else if(phase==3){var lights=Get(ed,"previewLighting");var key=(Light)lights.GetType().GetField("Key",F).GetValue(lights);Check(Quaternion.Angle(lightBeforeOrbit,key.transform.rotation)>10,"Camera lights do not follow orbit");Check(p.Length>0,"Orbit output missing");StudioSettings.Current.disableViewportAntialiasing=true;view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);}
 else if(phase==4){StudioSettings.Current.disableViewportAntialiasing=false;StudioSettings.Current.useViewportSmaa=true;view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);}
 else if(phase==5){var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/Editor/PreviewGrid.png");importer.textureCompression=TextureImporterCompression.Uncompressed;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=8;importer.mipmapFilter=TextureImporterMipFilter.KaiserFilter;importer.SaveAndReimport();ed.SetDisplayMode(true,true);}
 else{ed.SetDisplayMode(false,true);Check(ed.Transforms[0].GetComponent<Renderer>().sharedMaterial.shader.name=="MashBox/Studio/Preview","Unlit diagnostic path changed");ed.SetDisplayMode(true,true);ed.SetXRayMode(true);Check(ed.Transforms[0].GetComponent<Renderer>().sharedMaterial.shader.name=="MashBox/Studio/Preview","Xray diagnostic path changed");Check(doc.nodes[0].materials[0]==source,"Source assignment changed");Finish("PASS "+checks+" HDRP native camera material/metallic/smoothness/orbit/state/diagnostic checks; imported grid "+grid.width+"x"+grid.height+" mips="+grid.mipmapCount);return;}phase++;warmup=0;ready=EditorApplication.timeSinceStartup+1;view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string r){EditorApplication.update-=Tick;File.WriteAllText(Out("physical-camera-result.txt"),r);EditorApplication.delayCall+=()=>{if(view)view.Close();if(host)Object.DestroyImmediate(host);if(source&&!AssetDatabase.Contains(source))Object.DestroyImmediate(source);EditorApplication.delayCall+=()=>EditorApplication.Exit(r.StartsWith("PASS")?0:1);};}
}
